data.minimal_example:
import 'package:multi_state_button/multi_state_button.dart';

final MultiStateButtonController controller = MultiStateButtonController(initialStateName: 'Submit');

MultiStateButton(
  multiStateButtonController: controller,
  buttonStates: [
    ButtonState(
      stateName: 'Submit',
      child: Text('Submit'),
      onPressed: () => controller.setButtonState = 'Loading',
    ),
    ButtonState(
      stateName: 'Loading',
      child: CircularProgressIndicator(),
      onPressed: () => controller.setButtonState = 'Submit',
    ),
  ],
);
